NQA = [
 dict(id='NQ01', key='B304', tag='Hadiz · Bujari 304 · Abu Saʿid al-Judri', specs=['NQ-b304'],
  title='Bujari 304: «No he visto a nadie deficiente en razón y religión…»; y el propio Profeta explica la «deficiencia»: testimonio y menstruación',
  ref='al-Bujari, Sahih, Kitab al-hayd, «Bab tark al-ha’id al-sawm», n.º 304',
  ar_ref='صحيح البخاري ٣٠٤', site=HU, url='https://hadithunlocked.com/bukhari:304',
  es=['Nos contó Saʿid ibn Abi Maryam: nos informó Muhammad ibn Yaʿfar: me informó Zayd —es Ibn Aslam—, de ʿIyad ibn ʿAbd Allah, de Abu Saʿid al-Judri, que dijo: El Mensajero de Dios ﷺ salió, en [la fiesta del] Sacrificio o de la Ruptura del ayuno, al lugar de oración y pasó junto a las mujeres y dijo: «¡Oh congregación de mujeres! Dad limosna, pues se me ha mostrado que sois la mayoría de los habitantes del Fuego.» Dijeron: «¿Y por qué, Mensajero de Dios?» Dijo: «Maldecís mucho y sois desagradecidas con el cónyuge. [[k:No he visto a nadie, de entre los deficientes en razón y religión, que haga perder más el juicio al hombre sensato que una de vosotras.]]» Dijeron: «¿Y en qué consiste la deficiencia de nuestra religión y de nuestra razón, Mensajero de Dios?» Dijo: [[a:«¿No es el testimonio de la mujer como la mitad del testimonio del hombre?»]] Dijeron: «Sí.» Dijo: [[k:«Eso es de la deficiencia de su razón.»]] [[a:«¿No es verdad que cuando menstrúa no reza ni ayuna?»]] Dijeron: «Sí.» Dijo: [[k:«Eso es de la deficiencia de su religión.»]]'],
  prueba='Es el texto base del que parte toda la polémica. Según Abu Saʿid, el propio Profeta explica la expresión: la «deficiencia de razón» (nuqsan al-ʿaql) la ilustra con la regla del testimonio —el de la mujer vale la mitad del del hombre— y la «deficiencia de religión» con no rezar ni ayunar durante la menstruación. El hadiz trae su propia definición y en ninguna parte dice «la mitad de inteligencia»: lo que es «la mitad» es el testimonio (cf. Corán 2:282).',
  ojo='(1) La fórmula «mujer = mitad de inteligencia» no está en este texto ni en ninguna de las variantes que leí (busqué «نصف عقل»: no aparece). (2) La «deficiencia de religión» es no rezar ni ayunar durante la menstruación, que Dios mismo prescribe; los comentaristas lo señalan (Nawawi y Ibn Hayar: NQ38–NQ39). (3) Aun así el texto dice literalmente «deficientes en razón», y los exégetas (Razi, Baydawi, Alusi: NQ30–NQ33) lo generalizan a una superioridad intelectual masculina, mientras que juristas como Ibn Taymiyya lo limitan a la precisión al retener (dabt) en el testimonio (NQ49). (4) Cadena: Saʿid ibn Abi Maryam ← Muhammad ibn Yaʿfar ← Zayd ← ʿIyad ← Abu Saʿid; recogido por Bujari y Muslim (hadithunlocked lo marca «muttafaq ʿalayh»).',
  uso=USO),
 dict(id='NQ02', key='M79', tag='Hadiz · Muslim 79 · Ibn ʿUmar', specs=['NQ-m79'],
  title='Muslim 79 (Ibn ʿUmar): «el testimonio de dos mujeres equivale al de un hombre; esa es la deficiencia de la razón»',
  ref='Muslim, Sahih, Kitab al-iman, «Bab bayan nuqsan al-iman bi-nuqsan al-taʿat», n.º 79',
  ar_ref='صحيح مسلم ٧٩', site=HU, url='https://hadithunlocked.com/muslim:79',
  es=['Muhammad ibn Rumh ibn al-Muhayir al-Misri: nos informó al-Layth, de Ibn al-Had, de ʿAbd Allah ibn Dinar, de ʿAbd Allah ibn ʿUmar, del Mensajero de Dios ﷺ, que dijo: «¡Oh congregación de mujeres! Dad limosna y multiplicad el pedir perdón, pues se me ha mostrado que sois la mayoría de los habitantes del Fuego.» [[a:Dijo una mujer de entre ellas, de buen juicio (jazla):]] «¿Y por qué nosotras, Mensajero de Dios, somos la mayoría de los habitantes del Fuego?» Dijo: «Maldecís mucho y sois desagradecidas con el cónyuge. [[k:Y no he visto a nadie, de entre los deficientes en razón y religión, que domine más a un hombre de juicio [lubb] que vosotras.]]» Dijo ella: «Mensajero de Dios, ¿qué es la deficiencia de la razón y de la religión?» Dijo: «[[k:En cuanto a la deficiencia de la razón: el testimonio de dos mujeres equivale al testimonio de un hombre; esa es la deficiencia de la razón.]] [[a:Y [la mujer] permanece noches sin rezar y rompe el ayuno en Ramadán: esa es la deficiencia de la religión.]]»'],
  prueba='En esta versión el Profeta aplica el término directamente al testimonio («esa es la deficiencia de la razón»). El capítulo en que Muslim lo coloca, «Exposición de que la fe disminuye con la disminución de las obediencias», muestra cómo lo entendió: como un ejemplo de que fe y religión suben y bajan con el cumplimiento de los actos, no como un dictamen sobre capacidad mental (el título del capítulo lo vi en la página de Nawawi, NQ39).',
  ojo='Variante de formulación: «أغلب لذي لب منكن» («más capaces de dominar a un hombre de juicio») frente a «أذهب للب الرجل الحازم» de Bujari. La mujer que pregunta es descrita como «jazla»; Nawawi lo glosa «dueña de razón y criterio» (NQ39): los comentaristas notan que quien pregunta es una mujer de buen entendimiento. Que Muslim use el hadiz bajo «fe que disminuye» es una lectura del compilador, no una declaración sobre el origen (innato o no) de la «deficiencia».',
  uso=USO),
 dict(id='NQ03', key='B2658', tag='Hadiz · Bujari 2658 · Libro de los testimonios', specs=['NQ-b2658'],
  title='Bujari 2658: la misma explicación del Profeta, en el Libro de los testimonios («el testimonio de la mujer, la mitad…»)',
  ref='al-Bujari, Sahih, Kitab al-shahadat, n.º 2658',
  ar_ref='صحيح البخاري ٢٦٥٨', site=HU, url='https://hadithunlocked.com/bukhari:2658',
  es=['Nos contó Ibn Abi Maryam: nos informó Muhammad ibn Yaʿfar: me informó Zayd, de ʿIyad ibn ʿAbd Allah, de Abu Saʿid al-Judri, del Profeta ﷺ, que dijo: [[a:«¿No es el testimonio de la mujer como la mitad del testimonio del hombre?»]] Dijimos: «Sí.» Dijo: [[k:«Eso es de la deficiencia de su razón.»]]'],
  prueba='Bujari recoge solo la parte del testimonio cuando trata el testimonio de las mujeres: aquí el hadiz funciona como argumento jurídico, y el «la mitad» es explícitamente del testimonio (shahada). No hay ni rastro de «mitad de razón».',
  ojo='Es la misma cadena de NQ01 (Ibn Abi Maryam ← Muhammad ibn Yaʿfar ← Zayd ← ʿIyad ← Abu Saʿid) abreviada; no es una segunda transmisión independiente. Que al-Bujari (m. 256 H) lo ponga en el Libro de los testimonios muestra que ya en el siglo III H se leía como base de la regla procesal del «la mitad».',
  uso=USO),
 dict(id='NQ04', key='B1462', tag='Hadiz · Bujari 1462 · Abu Saʿid · Zaynab', specs=['NQ-b1462'],
  title='Bujari 1462 (Libro del zakat): la frase y, a continuación, la consulta de Zaynab, mujer de Ibn Masʿud',
  ref='al-Bujari, Sahih, Kitab al-zakat, n.º 1462',
  ar_ref='صحيح البخاري ١٤٦٢', site=HU, url='https://hadithunlocked.com/bukhari:1462',
  es=['«¡Oh congregación de mujeres! Dad limosna, pues se me ha mostrado que sois la mayoría de los habitantes del Fuego.» Dijeron: «¿Y por qué es eso, Mensajero de Dios?» Dijo: «Maldecís mucho y sois desagradecidas con el cónyuge. [[k:No he visto a nadie, de entre los deficientes en razón y religión, que haga perder más el juicio al hombre sensato que una de vosotras, oh congregación de mujeres.]]» Luego se marchó. Cuando llegó a su casa, [[a:vino Zaynab, la mujer de Ibn Masʿud, pidiendo permiso para entrar.]] Se dijo: «Mensajero de Dios, esta es Zaynab.» Dijo: «¿Cuál de las Zaynab?» Se dijo: «La mujer de Ibn Masʿud.» Dijo: «Sí, dejadla pasar.» Se le permitió y dijo: «¡Profeta de Dios! Hoy has ordenado la limosna y yo tenía una joya mía; quise dar limosna con ella, pero Ibn Masʿud afirma que él y su hijo [hijos] tienen más derecho que aquellos a quienes yo se la daría.» [[a:Dijo el Profeta ﷺ: «Ibn Masʿud ha dicho la verdad: tu marido y tu hijo son los que más derecho tienen a lo que des en limosna.»]]'],
  prueba='La misma escena (sermón a las mujeres en la fiesta) en el Libro del zakat. Tras la frase, el Profeta recibe a una de las mujeres presentes, que le plantea una consulta jurídica sobre su propia limosna, y le responde con una sentencia concreta. Sirve para ubicar el dicho en su situación: una exhortación a dar limosna dirigida a mujeres, con la crítica (maldecir, desagradecer al cónyuge) como motivo.',
  ojo='Esta versión no trae la explicación de «nuqsan» (la dan NQ01 y NQ03). Que el Profeta atienda a Zaynab y resuelva su consulta no demuestra por sí solo nada sobre su capacidad intelectual: lo uso solo como contexto. Cuidado con fundir escenas: según Ahmad 8862 (NQ07), contado por Abu Huraira, Zaynab oye el dicho, va primero a su marido y luego pregunta al Profeta qué es la deficiencia: orden y detalles distintos.',
  uso=USO),
 dict(id='NQ05', key='AD4679', tag='Hadiz · Abu Dawud 4679 · Ibn ʿUmar', specs=['NQ-ad4679'],
  title='Abu Dawud 4679 (Ibn ʿUmar): «ناقصات عقل ولا دين» — el testimonio de dos mujeres vale por uno; la religión, los días sin rezar',
  ref='Abu Dawud, Sunan, Kitab al-sunna, n.º 4679', ar_ref='سنن أبي داود ٤٦٧٩', site=HU, url='https://hadithunlocked.com/abudawud:4679',
  es=['Nos contó Ahmad ibn ʿAmr ibn al-Sarh: nos contó Ibn Wahb, de Bakr ibn Mudar, de Ibn al-Had, de ʿAbd Allah ibn Dinar, de ʿAbd Allah ibn ʿUmar, que el Mensajero de Dios ﷺ dijo: [[k:«No he visto a nadie, de entre los deficientes en razón ni religión, que domine más a un hombre de juicio que vosotras.»]] Ella dijo: «¿Qué es la deficiencia de la razón y de la religión?» Dijo: [[k:«En cuanto a la deficiencia de la razón: el testimonio de dos mujeres es el testimonio de un hombre.»]] [[a:Y en cuanto a la deficiencia de la religión: una de vosotras rompe el ayuno en Ramadán y se queda días sin rezar.»]]'],
  prueba='Es la versión de Ibn ʿUmar (como en Muslim 79, NQ02) en otra gran colección, aquí en el Libro de la sunna (creencia). Confirma el mismo patrón: «deficiencia de razón» = testimonio; «deficiencia de religión» = días sin rezar y ayuno de Ramadán.',
  ojo='Variante de texto: «ناقصات عقل ولا دين» («…ni religión») en lugar de «عقل ودين»; es un detalle de la edición que muestra, sin más, que el texto varía algo entre colecciones. Grado en hadithunlocked: sahih (al-Albani). Comparte la cadena de Ibn ʿUmar con Muslim 79 (…Ibn al-Had ← ʿAbd Allah ibn Dinar ← Ibn ʿUmar): no es transmisión independiente de la que ya vimos.',
  uso=USO),
 dict(id='NQ06', key='T2613', tag='Hadiz · Tirmidhi 2613 · Abu Huraira', specs=['NQ-t2613'],
  title='Tirmidhi 2613 (Abu Huraira): «…más [capaces de dominar] a los dotados de entendimiento y criterio»; la menstruación «tres y cuatro [días]»',
  ref='al-Tirmidhi, Yamiʿ, Kitab al-iman, n.º 2613', ar_ref='جامع الترمذي ٢٦١٣', site=HU, url='https://hadithunlocked.com/tirmidhi:2613',
  es=['Nos contó Abu ʿAbd Allah Hurayim ibn Misʿar al-Azdi al-Tirmidhi: nos contó ʿAbd al-ʿAziz ibn Muhammad, de Suhayl ibn Abi Salih, de su padre, de Abu Huraira, que el Mensajero de Dios ﷺ predicó a la gente y los exhortó; luego dijo: «¡Oh congregación de mujeres! Dad limosna, pues sois la mayoría de los habitantes del Fuego.» Dijo una mujer de entre ellas: «¿Y por qué, Mensajero de Dios?» Dijo: [[a:«Por la abundancia de vuestras maldiciones —quiere decir: y vuestra ingratitud con el cónyuge.»]] Y dijo: [[k:«No he visto a nadie, de entre los deficientes en razón y religión, que domine más a los dotados de entendimiento y de criterio [dhawu l-albab wa-dhawu l-raʾy] que vosotras.»]] Dijo una mujer de entre ellas: «¿Y cuál es la deficiencia de su religión y de su razón?» Dijo: [[k:«El testimonio de dos mujeres de vosotras vale por el de un hombre,]] [[a:y la deficiencia de vuestra religión es la menstruación: una de vosotras permanece tres y cuatro [días] sin rezar.»]]'],
  prueba='Versión de Abu Huraira con la misma explicación del Profeta. Aquí el término «dotados de entendimiento y criterio» refuerza que la «deficiencia» se contrasta con el hombre de buen juicio, no con el hombre en general.',
  ojo='Texto de Abu Huraira (otra rama que la de Abu Saʿid o Ibn ʿUmar): sí aporta un tercer Compañero para el mismo dicho. Grado en hadithunlocked: sahih (al-Albani; Zubayr ʿAli Zaʾi). La cadena de Tirmidhi (Hurayim ← ʿAbd al-ʿAziz ← Suhayl ← Abu Salih ← Abu Huraira) es distinta de la de Ahmad 8862 (NQ07), aunque ambas son por Abu Huraira.',
  uso=USO),
 dict(id='NQ07', key='AH8862', tag='Hadiz · Ahmad 8862 · Abu Huraira', specs=['NQ-ah8862'],
  title='Ahmad 8862 (Abu Huraira): variante «nawaqis ʿuqul wa-din»; Zaynab consulta al Profeta y él da la definición',
  ref='Ahmad ibn Hanbal, Musnad, n.º 8862 (numeración de hadithunlocked)', ar_ref='مسند أحمد ٨٨٦٢', site=HU, url='https://hadithunlocked.com/ahmad:8862',
  es=['Nos contó Sulayman: nos informó Ismaʿil: me informó ʿAmr —es decir, Ibn Abi ʿAmr—, de Abu Saʿid al-Maqburi, de Abu Huraira, que el Profeta ﷺ se retiró un día de la [oración de la] mañana, fue a las mujeres en la mezquita y se detuvo ante ellas diciendo: «¡Oh congregación de mujeres! [[k:No he visto a nadie, de entre los deficientes en razones y religión, que arrebate más los corazones de los dotados de entendimiento que vosotras.]] Y he visto que sois la mayoría de los habitantes del Fuego el Día de la Resurrección; acercaos a Dios cuanto podáis.» Y entre las mujeres estaba la mujer de ʿAbd Allah ibn Masʿud; fue a ʿAbd Allah, le contó lo que había oído del Mensajero de Dios ﷺ y tomó una joya suya. Dijo Ibn Masʿud: «¿Adónde vas con esa joya?» Dijo ella: «Me acerco con ella a Dios y a su Mensajero; quizá Dios no me haga de los habitantes del Fuego.» Dijo: «¡Ay de ti! Ven, dámela en limosna a mí y a mis hijos; soy un destino adecuado.» Dijo: «¡No, por Dios, hasta que vaya con ella al Profeta!» Fue a pedir permiso al Profeta ﷺ y dijeron al Profeta: «Esta es Zaynab, pide permiso, Mensajero de Dios.» Dijo: «¿Cuál de las Zaynab?» Dijeron: «La mujer de ʿAbd Allah ibn Masʿud.» Dijo: «Dejadla entrar.» Entró y dijo: «Mensajero de Dios, oí de ti unas palabras, volví a Ibn Masʿud y se las conté, y tomé mi joya para acercarme con ella a Dios y a ti, con la esperanza de que Dios no me haga de los habitantes del Fuego; pero Ibn Masʿud me dijo: ‹Dámela en limosna a mí y a mis hijos, que somos un destino adecuado›, y le dije: ‹[no] hasta que pida permiso al Profeta›.» Dijo el Profeta ﷺ: «Dásela en limosna a él y a sus hijos, pues son un destino adecuado.» Luego dijo: «Mensajero de Dios, ¿qué significa lo que te oí cuando te detuviste ante nosotras: ‹no he visto jamás nada deficiente en razones y religión que arrebate más los corazones de los dotados de entendimiento que vosotras›?» Dijo: «Mensajero de Dios, ¿cuál es la deficiencia de nuestra religión y de nuestras razones?» Dijo: [[a:«En cuanto a lo que mencionas de la deficiencia de vuestra religión: la menstruación que os alcanza; una de vosotras se queda lo que Dios quiera sin rezar ni ayunar: eso es de la deficiencia de vuestra religión.]] [[k:Y en cuanto a lo que mencionas de la deficiencia de vuestras razones: vuestro testimonio, pues el testimonio de la mujer es sencillamente la mitad del testimonio…]]»'],
  prueba='Versión larga de Abu Huraira, con la anécdota de Zaynab, y con una variante de la fórmula: «nawaqis ʿuqul» (plural de «razones»). El Profeta da la misma explicación: la «deficiencia de razones» es el testimonio, con la mitad como unidad de cuenta.',
  ojo='El texto de hadithunlocked termina así: «…شهادة المرأة نصف شهادة» (la mitad del testimonio), sin «الرجل» al final: lo traduzco tal cual y no completo la frase. Grado: Shuʿayb al-Arnaʾut, «cadena buena»; hadithunlocked muestra además una nota de al-Haythami («sus hombres son fiables»), pero con otro número de edición, así que la cito con reserva.',
  uso=USO),
 dict(id='NQ08', key='IH3323', tag='Hadiz/relato · Ibn Hibban 3323 · Ibn Masʿud', specs=['NQ-ih3323'],
  title='Ibn Hibban 3323 (Ibn Masʿud): «…más capaces de dominar a los hombres con mando sobre su asunto» — y la frase queda en boca de ʿAbd Allah',
  ref='Ibn Hibban, Sahih (al-Ihsan), n.º 3323 (numeración de hadithunlocked)', ar_ref='صحيح ابن حبان ٣٣٢٣', site=HU, url='https://hadithunlocked.com/ibnhibban:3323',
  es=['Nos informó al-Fadl ibn al-Hubab: nos contó Muhammad ibn Bashshar: nos contó Muhammad, de Shuʿba, de al-Hakam: oí a Dharr contar, de Wail ibn Mahana, de Ibn Masʿud, del Profeta ﷺ, que dijo a las mujeres: «Dad limosna, pues sois la mayoría de los habitantes del Fuego.» Dijo una mujer que no era de las distinguidas: «¿Por qué?» Dijo: [[a:«Porque maldecís mucho y sois desagradecidas con el cónyuge.»]] [[k:Dijo ʿAbd Allah: «No hay entre los deficientes en razón y religión quienes más dominen a los hombres con mando sobre su asunto que las mujeres.»]] Se dijo: «¿Y cuál es la deficiencia de su razón y de su religión?» Dijo: [[k:«En cuanto a la deficiencia de su razón: el testimonio de dos mujeres es el testimonio de un hombre»]]; y en cuanto a la deficiencia de su religión: a una de ellas le llegan tantos y tantos días en que no reza ni una sola oración.'],
  prueba='Cuarta rama de Compañeros (Ibn Masʿud, junto a Abu Saʿid, Ibn ʿUmar y Abu Huraira): el mismo patrón explicativo (testimonio y días sin rezar), con la fórmula «ذوي الأمر على أمرهم» («los que tienen mando sobre su asunto»).',
  ojo='Aquí «Dijo ʿAbd Allah» abre la frase clave, aunque la cadena comienza «del Profeta ﷺ»: el texto no deja claro si ʿAbd Allah cita al Profeta o comenta con sus propias palabras (compárese con NQ09, donde se lee directamente en boca de Ibn Masʿud). Grado en hadithunlocked: «débil» (Shuʿayb al-Arnaʾut). La cadena pasa por Wail ibn Mahana (nombre que no he evaluado).',
  uso=USO),
 dict(id='NQ09', key='IAS31048', tag='Dicho de Compañero · Ibn Abi Shayba 31048 · Ibn Masʿud', specs=['NQ-ias31048'],
  title='Ibn Abi Shayba 31048: en boca de Ibn Masʿud («deficiente en religión y criterio»), sin atribuirlo al Profeta',
  ref='Ibn Abi Shayba, Musannaf, n.º 31048 (numeración de hadithunlocked)', ar_ref='مصنف ابن أبي شيبة ٣١٠٤٨', site=HU, url='https://hadithunlocked.com/ibnabishaybah:31048',
  es=['Nos contó Abu Muʿawiya, de al-Aʿmash, de Dharr, de Wail ibn Mahana, que dijo: Dijo ʿAbd Allah [ibn Masʿud]: [[k:«No he visto a nadie deficiente en religión y criterio que domine más a los hombres con mando sobre su asunto que las mujeres.»]] Dijeron: «Abu ʿAbd al-Rahman, ¿y cuál es la deficiencia de su religión?» Dijo: [[a:«Que dejan la oración los días de su menstruación.»]] Dijeron: «¿Y cuál es la deficiencia de su razón?» Dijo: [[a:«Que no es válido el testimonio de dos mujeres sin [el de] un hombre.»]]'],
  prueba='En el Musannaf de Ibn Abi Shayba (m. 235 H) la frase aparece como palabra de Ibn Masʿud, con las mismas dos explicaciones (días de menstruación; testimonio de dos mujeres con un hombre). Es evidencia de que la fórmula circulaba entre los Compañeros/tabiʿun en los mismos términos que en los hadices.',
  ojo='Aquí no hay «قال رسول الله»: tal como se lee, es dicho de Ibn Masʿud (mawquf); no sé cómo lo clasifican los críticos de hadiz. Cambia «ʿaql» por «raʾy» («criterio»). Comparte la cadena Dharr ← Wail ibn Mahana con NQ08 (que Shuʿayb al-Arnaʾut califica de débil); hadithunlocked no da grado para esta entrada.',
  uso=USO),
]
